-- MedCare Pharma MySQL database export (corrected data)
-- Tables: demand, inventory, batches, sales
-- Source data intentionally excludes forecasts/alerts/recommendations;
-- those are calculated by the application.

CREATE DATABASE IF NOT EXISTS medcare;
USE medcare;

DROP TABLE IF EXISTS sales;
DROP TABLE IF EXISTS batches;
DROP TABLE IF EXISTS inventory;
DROP TABLE IF EXISTS demand;

CREATE TABLE demand (
  date DATE NOT NULL,
  sku_id VARCHAR(20) NOT NULL,
  warehouse_id VARCHAR(20) NOT NULL,
  demand_qty INT NOT NULL,
  promotion_flag TINYINT NOT NULL DEFAULT 0,
  season_flag TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE inventory (
  sku_id VARCHAR(20) NOT NULL,
  warehouse_id VARCHAR(20) NOT NULL,
  current_stock INT NOT NULL,
  min_threshold INT NOT NULL,
  safety_stock INT NOT NULL,
  capacity INT NOT NULL,
  lead_time_days INT NOT NULL
) ENGINE=InnoDB;

CREATE TABLE batches (
  batch_id VARCHAR(20) PRIMARY KEY,
  sku_id VARCHAR(20) NOT NULL,
  warehouse_id VARCHAR(20) NOT NULL,
  quantity INT NOT NULL,
  expiry_date DATE NOT NULL
) ENGINE=InnoDB;

CREATE TABLE sales (
  date DATE NOT NULL,
  sku_id VARCHAR(20) NOT NULL,
  warehouse_id VARCHAR(20) NOT NULL,
  units_sold INT NOT NULL,
  unit_price DECIMAL(10,2) NOT NULL,
  revenue DECIMAL(12,2) NOT NULL
) ENGINE=InnoDB;

START TRANSACTION;
COMMIT;

-- Recommended indexes
CREATE INDEX idx_demand_sku_warehouse ON demand(sku_id, warehouse_id);
CREATE INDEX idx_demand_date ON demand(date);
CREATE INDEX idx_inventory_sku_warehouse ON inventory(sku_id, warehouse_id);
CREATE INDEX idx_batches_sku_warehouse ON batches(sku_id, warehouse_id);
CREATE INDEX idx_batches_expiry ON batches(expiry_date);
CREATE INDEX idx_sales_sku_warehouse ON sales(sku_id, warehouse_id);
CREATE INDEX idx_sales_date ON sales(date);
